1: import { describe, expect, it } from "vitest";
2: import { remark } from "remark";
3: import remarkCitationParser from "./remarkCitationParser";
4: 
5: function parse(content: string) {
6:   const processor = remark().use(remarkCitationParser);
7:   return processor.runSync(processor.parse(content));
8: }
9: 
10: describe("remarkCitationParser production pipeline", () => {
11:   it("carries the exact range and surrounding text into the citation node", () => {
12:     expect(parse("Before 【1†L25-L30】 after.").children).toMatchObject([
13:       {
14:         type: "paragraph",
15:         children: [
16:           { type: "text", value: "Before " },
17:           {
18:             type: "custom-citation",
19:             data: {
20:               hName: "ol-citation",
21:               hProperties: { cursor: "1", start: "25", end: "30" },
22:             },
23:           },
24:           { type: "text", value: " after." },
25:         ],
26:       },
27:     ]);
28:   });
29: 
30:   it("preserves the distinct generic citation payload", () => {
31:     expect(parse("【12†source】").children).toMatchObject([
32:       {
33:         type: "paragraph",
34:         children: [
35:           {
36:             type: "custom-citation",
37:             data: { hName: "ol-citation", hProperties: { cursor: "12" } },
38:           },
39:         ],
40:       },
41:     ]);
42:   });
43: 
44:   it("coalesces adjacent equal cursors without dropping a different cursor", () => {
45:     const paragraph = parse("【1†L1-L2】【1†L3-L4】【2†source】").children[0];
46:     expect(paragraph).toMatchObject({
47:       type: "paragraph",
48:       children: [
49:         { type: "custom-citation", data: { hProperties: { cursor: "1" } } },
50:         { type: "custom-citation", data: { hProperties: { cursor: "2" } } },
51:       ],
52:     });
53:     expect(paragraph && "children" in paragraph && paragraph.children).toHaveLength(2);
54:   });
55: 
56:   it("does not coalesce citations separated by ordinary text", () => {
57:     expect(parse("【3†source】 and 【3†source】").children).toMatchObject([
58:       {
59:         type: "paragraph",
60:         children: [
61:           { type: "custom-citation", data: { hProperties: { cursor: "3" } } },
62:           { type: "text", value: " and " },
63:           { type: "custom-citation", data: { hProperties: { cursor: "3" } } },
64:         ],
65:       },
66:     ]);
67:   });
68: 
69:   it("leaves code and malformed delimiters alone", () => {
70:     expect(parse("`【1†L2-L3】` 【not-a-cursor†source】").children).toMatchObject([
71:       {
72:         type: "paragraph",
73:         children: [
74:           { type: "inlineCode", value: "【1†L2-L3】" },
75:           { type: "text", value: " 【not-a-cursor†source】" },
76:         ],
77:       },
78:     ]);
79:   });
80: 
81:   it("preserves an empty document without manufacturing a citation", () => {
82:     expect(parse("").children).toEqual([]);
83:   });
84: });
